// Parse and validate JD extraction output
const raw = $input.item.json.output;

let jd;
try {
  const cleaned = raw.replace(/```json\n?/gi, '').replace(/```\n?/gi, '').trim();
  jd = JSON.parse(cleaned);
} catch (e) {
  // Fallback structure if parsing fails
  jd = {
    role_title: 'Unknown Role',
    seniority_level: 'Mid',
    department: 'General',
    must_have_skills: [],
    good_to_have_skills: [],
    min_experience_years: 0,
    max_experience_years: null,
    key_responsibilities: [],
    industry_preference: 'Any',
    education_requirement: 'Any',
    ctc_budget_max: null,
    evaluation_weights: {
      technical_skills_match: 30,
      experience_relevance: 30,
      leadership_fitment: 20,
      education_fitment: 20
    },
    jd_summary: 'Role as specified by the hiring team.'
  };
}

// Store JD in workflow static data so all loop iterations can access it
return {
  json: {
    jd_parsed: jd,
    jd_raw: raw,
    jd_processed_at: new Date().toISOString()
  }
};

// Merge JD context into each candidate row so loop iterations carry it
const jdData = $('Parse JD Output').item.json;
const candidates = $input.all();

return candidates.map(c => ({
  json: {
    ...c.json,
    _jd: jdData.jd_parsed,
    _jd_processed_at: jdData.jd_processed_at
  }
}));

