  "ctc_fit": "<Within Budget / Over Budget / Unknown>",
  "experience_fit": "<Under-qualified / Well-matched / Over-qualified>",
  "recommendation": "<One sentence specific to this role>",
  "interview_questions": ["<targeted question 1 based on gaps>", "<targeted question 2>", "<targeted question 3>"]
}

Return ONLY the JSON. No preamble.

parameters.jsCode:
// Parse evaluator output and merge all data
const candidateRow = $('Loop Over Candidates').item.json;
const rawOutput = $input.item.json.output;

let evaluation;
try {
  const cleaned = rawOutput.replace(/```json\n?/gi, '').replace(/```\n?/gi, '').trim();
  evaluation = JSON.parse(cleaned);
} catch (e) {
  evaluation = {
    overall_score: 50,
    technical_skills_score: 50,
    experience_score: 50,
    leadership_score: 50,
    education_score: 50,
    skills_matched: [],
    skills_missing: [],
    strengths: 'Could not parse|Manual review needed|N/A',
    weaknesses: 'Could not parse|Manual review needed',
    ctc_fit: 'Unknown',
    experience_fit: 'Unknown',
    recommendation: 'Manual review required.',
    interview_questions: ['Please review manually.']
  };
}

const jd = candidateRow._jd;

return {
  json: {
    // Candidate fields
    name: candidateRow['Name'],
    email: candidateRow['Email'],
    years_exp: candidateRow['Years Exp'],
    expected_ctc: candidateRow['Expected CTC'],
    key_skills: candidateRow['Key Skills'],
    professional_summary: candidateRow['Professional Summary'],
    education_summary: candidateRow['Education Summary'],

    // JD context
    jd_role_title: jd.role_title,
    jd_seniority: jd.seniority_level,
    jd_department: jd.department,
    jd_summary: jd.jd_summary,
    jd_must_have_skills: jd.must_have_skills.join(', '),

    // Scores
    overall_score: evaluation.overall_score,
    technical_skills_score: evaluation.technical_skills_score,
    experience_score: evaluation.experience_score,
    leadership_score: evaluation.leadership_score,
    education_score: evaluation.education_score,

    // Evaluation details
    skills_matched: (evaluation.skills_matched || []).join(', '),
    skills_missing: (evaluation.skills_missing || []).join(', '),
    strengths: evaluation.strengths,
    weaknesses: evaluation.weaknesses,
    ctc_fit: evaluation.ctc_fit,
    experience_fit: evaluation.experience_fit,
    recommendation: evaluation.recommendation,
    interview_questions: (evaluation.interview_questions || []).join(' | '),

    // Status
    status: evaluation.overall_score >= 70 ? 'SHORTLISTED' : 'NOT SHORTLISTED',
    evaluated_at: new Date().toISOString()
  }
};

