=<!DOCTYPE html>
<html>
<head>
<style>
  body{font-family:Arial,sans-serif;max-width:700px;margin:0 auto;color:#222;}
  .header{background:linear-gradient(135deg,#1a73e8,#0d47a1);color:white;padding:26px 32px;border-radius:10px 10px 0 0;}
  .header h1{margin:0;font-size:20px;}
  .header p{margin:6px 0 0;opacity:.85;font-size:13px;}
  .body{background:#fff;padding:28px 32px;border:1px solid #dce6f0;}
  .score-row{display:flex;gap:10px;margin:16px 0;}
  .score-box{flex:1;background:#f0f7ff;border:1px solid #bbdefb;padding:12px;border-radius:8px;text-align:center;}
  .score-box .val{font-size:22px;font-weight:bold;color:#1a73e8;}
  .score-box .lbl{font-size:11px;color:#666;text-transform:uppercase;margin-top:2px;}
  .big-score{background:#e8f5e9;border:2px solid #43a047;border-radius:50px;display:inline-block;padding:10px 28px;font-size:30px;font-weight:bold;color:#2e7d32;margin:12px 0;}
  .candidate-card{background:#f8f9fa;border-left:4px solid #1a73e8;padding:14px 18px;border-radius:6px;margin:16px 0;font-size:13px;}
  .candidate-card p{margin:5px 0;}
  .section{margin:18px 0;}
  .section h3{color:#1a73e8;font-size:14px;text-transform:uppercase;letter-spacing:.4px;border-bottom:1px solid #e0e0e0;padding-bottom:5px;margin-bottom:10px;}
  .tag{display:inline-block;padding:4px 10px;border-radius:12px;font-size:12px;margin:3px;}
  .tag-match{background:#e8f5e9;color:#2e7d32;}
  .tag-miss{background:#fce4ec;color:#c62828;}
  .tag-q{background:#f3e5f5;color:#6a1b9a;}
  .fit-badge{display:inline-block;padding:5px 14px;border-radius:20px;font-size:13px;font-weight:bold;margin:4px;}
  .fit-good{background:#e8f5e9;color:#2e7d32;}
  .fit-warn{background:#fff3e0;color:#e65100;}
  .fit-bad{background:#fce4ec;color:#c62828;}
  .footer{background:#f5f7f9;padding:12px 32px;font-size:11px;color:#999;border-radius:0 0 10px 10px;}
</style>
</head>
<body>
<div class="header">
  <h1>🏆 Strong JD Match — Shortlisted Candidate</h1>
  <p>Role: {{ $('Parse Evaluation Output').item.json.jd_role_title }} · {{ $('Parse Evaluation Output').item.json.jd_seniority }} ·{{ $('Parse Evaluation Output').item.json.jd_department }} </p>
</div>
<div class="body">
  <div style="text-align:center">
    <div class="big-score"> {{ $('Parse Evaluation Output').item.json.overall_score }}/ 100</div>
    <p style="color:#2e7d32;font-weight:bold;margin:4px 0">SHORTLISTED — Proceed to Interview</p>
  </div>

  <div class="candidate-card">
    <p><strong>👤 Name:</strong> {{ $('Parse Evaluation Output').item.json.name }}</p>
    <p><strong>📧 Email:</strong> {{ $('Parse Evaluation Output').item.json.email }}</p>
    <p><strong>💼 Experience:{{ $json['Years Experience'] }}</strong>  years &nbsp;|&nbsp; <strong>CTC Fit:</strong> <span class="fit-badge {{ $json.ctc_fit === 'Within Budget' ? 'fit-good' : $json.ctc_fit === 'Over Budget' ? 'fit-bad' : 'fit-warn' }}"></span>{{ $('Parse Evaluation Output').item.json.ctc_fit }}</p>
    <p><strong>📊 Experience Fit:</strong> <span class="fit-badge {{ $json.experience_fit === 'Well-matched' ? 'fit-good' : 'fit-warn' }}">{{ $('Parse Evaluation Output').item.json.experience_fit }}</span></p>
  </div>

  <div class="section">
    <h3>📊 Score Breakdown vs JD</h3>
    <div class="score-row">
      <div class="score-box"><div class="val">{{ $('Parse Evaluation Output').item.json.technical_skills_score }}</div><div class="lbl">Technical</div></div>
      <div class="score-box"><div class="val">{{ $('Parse Evaluation Output').item.json.experience_score }}</div><div class="lbl">Experience</div></div>
      <div class="score-box"><div class="val">{{ $('Parse Evaluation Output').item.json.leadership_score }}</div><div class="lbl">Leadership</div></div>
      <div class="score-box"><div class="val">{{ $('Parse Evaluation Output').item.json.education_score }}</div><div class="lbl">Education</div></div>
    </div>
  </div>

  <div class="section">
    <h3>✅ JD Skills Matched</h3>
    {{ $('Parse Evaluation Output').item.json.skills_matched.split(',').map(s => '<span class="tag tag-match">' + s.trim() + '</span>').join('') }}
  </div>

  <div class="section">
    <h3>⚠️ JD Skills Missing</h3>
    {{  $('Parse Evaluation Output').item.json.skills_missing? $json.skills_missing.split(',').map(s => '<span class="tag tag-miss">' + s.trim() + '</span>').join('') : '<span style="color:#999">No critical gaps</span>' }}
  </div>

  <div class="section">
    <h3>💪 Strengths (Role-Specific)</h3>
    {{$('Parse Evaluation Output').item.json.strengthssplit('|').map(s => '<p style="margin:5px 0;background:#f0f7ff;padding:8px 12px;border-radius:5px;font-size:13px;">• ' + s.trim() + '</p>').join('') }}
  </div>

  <div class="section">
    <h3>❓ Suggested Interview Questions</h3>
    {{ $('Parse Evaluation Output').item.json.interview_questions.split('|').map((q,i) => '<p style="margin:6px 0;font-size:13px;"><strong>Q' + (i+1) + ':</strong> ' + q.trim() + '</p>').join('') }}
  </div>

  <div class="section">
    <h3>🤖 AI Recommendation</h3>
    <p style="background:#e8f5e9;padding:12px;border-radius:6px;font-size:13px;">{{ $('Parse Evaluation Output').item.json.recommendation }}</p>
  </div>

  <div style="background:#f0f7ff;border:1px solid #bbdefb;padding:16px;border-radius:8px;margin-top:20px;">
    <strong>Next Step:</strong> Review and reply <strong>APPROVE</strong> or <strong>REJECT</strong> within 48 hours.
  </div>
</div>
<div class="footer">AI Evaluator · Role: {{ $('Parse Evaluation Output').item.json.jd_role_title }}·{{ $('Parse Evaluation Output').item.json.evaluated_at }} </div>
</body>
</html>
